-- Least-privilege application role (run ONCE per environment by an operator with the RDS master credential,
-- after the first `migrate` task). Web + worker connect as this role; only the migrate task uses the master user.
-- The password is generated by the operator and stored ONLY in Secrets Manager (<env>/db-app-password as
-- {"username":"projectos_app","password":"..."}) — never in this repository, Terraform state or a ticket.
--   psql "$MASTER_URL" -v app_password="$GENERATED" -f infra/sql/app-role.sql
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'projectos_app') THEN
    CREATE ROLE projectos_app LOGIN;
  END IF;
END $$;
ALTER ROLE projectos_app PASSWORD :'app_password';
ALTER ROLE projectos_app SET statement_timeout = '30s';
ALTER ROLE projectos_app SET idle_in_transaction_session_timeout = '60s';
GRANT CONNECT ON DATABASE projectos TO projectos_app;
GRANT USAGE ON SCHEMA public TO projectos_app;
-- DML only. No DDL, no TRUNCATE, no ownership: the app cannot disable the append-only audit triggers.
GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA public TO projectos_app;
GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA public TO projectos_app;
-- Tables created by future migrations (run as the master user) get the same grants automatically.
ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO projectos_app;
ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT USAGE, SELECT ON SEQUENCES TO projectos_app;
-- The readiness probe counts applied migrations.
GRANT USAGE ON SCHEMA drizzle TO projectos_app;
GRANT SELECT ON drizzle.__drizzle_migrations TO projectos_app;
